//! Minimal GPUI hello world, written against the gpui contract.
//!
//! The code never names a fork: `gpui` is bound to the provider chosen in
//! Cargo.toml via a dependency rename. Swap providers with:
//!
//!     cargo gocar add gpui-ce
//!     cargo gocar lock
//!
//! then `cargo build --locked`.

use gpui::*;

struct HelloWorld;

impl Render for HelloWorld {
    fn render(&mut self, _window: &mut Window, _cx: &mut Context<Self>) -> impl IntoElement {
        div()
            .flex()
            .size_full()
            .bg(rgb(0x101418))
            .justify_center()
            .items_center()
            .child(
                div()
                    .text_xl()
                    .text_color(rgb(0xffffff))
                    .child("Hello from gocar!"),
            )
    }
}

fn main() {
    Application::new().run(|cx: &mut App| {
        cx.open_window(WindowOptions::default(), |_, cx| cx.new(|_cx| HelloWorld))
            .unwrap();
    });
}

